public class MainActivity extends Activity {
 static final String ACCOUNT="charlie.sungjin@gmail.com";
 LinearLayout body; boolean unlocked=false;long pausedAt=0;
 final ArrayList<Long> calendarIds=new ArrayList<>();Spinner calendars;
 @Override public void onCreate(Bundle b){super.onCreate(b);login("login");}
 @Override public void onPause(){super.onPause();pausedAt=System.currentTimeMillis();}
 @Override public void onResume(){super.onResume();if(unlocked&&pausedAt>0&&System.currentTimeMillis()-pausedAt>60000){unlocked=false;login("login");}else if(unlocked)home();}
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);}
 GradientDrawable background(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 void screen(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(246,248,242));body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(24),dp(30),dp(24),dp(30));scroll.addView(body);setContentView(scroll);if(Build.VERSION.SDK_INT>=30)scroll.setOnApplyWindowInsetsListener((v,insets)->{Insets bars=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});text("◉ ORBIT",26,Color.rgb(52,86,231));text("나의 시간 공간 · ANDROID",11,Color.rgb(116,138,175));}
 void text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(10),0,dp(10));body.addView(t);}
 EditText input(String hint,boolean password){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine();e.setTextSize(15);e.setTextColor(Color.rgb(49,73,111));e.setInputType(password?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_CLASS_TEXT);e.setPadding(dp(13),dp(11),dp(13),dp(11));e.setBackground(background(Color.WHITE,10));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(53));p.topMargin=dp(10);body.addView(e,p);return e;}
 void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(Color.WHITE);b.setBackground(background(Color.rgb(57,95,235),12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.topMargin=dp(12);body.addView(b,p);b.setOnClickListener(v->{try{action.run();}catch(Exception ex){message("처리할 수 없습니다. 입력과 권한을 확인하세요.");}});}
 void message(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("확인",null).show();}
 void login(String mode){screen();boolean configured=LocalStore.prefs(this).contains("password");String actual=!configured?"setup":mode;boolean change="change".equals(actual),setup="setup".equals(actual);text(setup?"초기 비밀번호 설정":change?"비밀번호 변경":"비밀번호를 입력하세요",23,Color.rgb(48,71,107));text("휴대폰의 검토함은 기기에만 보관합니다. PC와 별개의 비밀번호입니다.",12,Color.rgb(113,133,164));EditText old=change?input("현재 비밀번호",true):null;EditText pass=input(setup?"새 비밀번호 (8자 이상)":change?"새 비밀번호":"비밀번호",true);EditText confirm=setup||change?input("비밀번호 확인",true):null;button(setup?"초기 설정하고 시작":change?"비밀번호 변경":"로그인",()->{String p=pass.getText().toString();new Thread(()->{try{if((setup||change)&&!p.equals(confirm.getText().toString()))throw new Exception("비밀번호 확인이 일치하지 않습니다.");if(change&&!LocalStore.verify(this,old.getText().toString()))throw new Exception("현재 비밀번호를 확인하세요.");if(setup||change)LocalStore.password(this,p);else if(!LocalStore.verify(this,p))throw new Exception("비밀번호를 확인하세요.");runOnUiThread(()->{unlocked=!change;if(change)login("login");else home();});}catch(Exception ex){runOnUiThread(()->message(ex.getMessage()==null?"로그인 실패":ex.getMessage()));}}).start();});if(configured){button(change?"로그인으로 돌아가기":"비밀번호 변경",()->login(change?"login":"change"));}text("비밀번호 분실 시 자동 복구를 제공하지 않습니다.",11,Color.rgb(139,152,174));}
 boolean calendarPermission(){return checkSelfPermission(Manifest.permission.READ_CALENDAR)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.WRITE_CALENDAR)==PackageManager.PERMISSION_GRANTED;}
 void home(){screen();text("메시지를 일정으로, 하루를 가볍게.",23,Color.rgb(48,71,107));text("카카오톡 알림 → 확인 → Google 캘린더 → PC 웹",12,Color.rgb(104,129,167));button("① 카카오톡 알림 접근 권한 설정",()->startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)));Switch capture=new Switch(this);capture.setText("카카오톡 알림 후보 수집");capture.setTextSize(14);capture.setPadding(0,dp(18),0,dp(12));capture.setChecked(LocalStore.prefs(this).getBoolean("capture",false));capture.setOnCheckedChangeListener((b,on)->LocalStore.prefs(this).edit().putBoolean("capture",on).apply());body.addView(capture);button("② 휴대폰 캘린더 접근 권한 허용",()->requestPermissions(new String[]{Manifest.permission.READ_CALENDAR,Manifest.permission.WRITE_CALENDAR},10));text("Google 계정: "+ACCOUNT,12,Color.rgb(79,109,169));calendars=new Spinner(this);body.addView(calendars);loadCalendars();button("Google 계정 동기화 설정",()->startActivity(new Intent(Settings.ACTION_SYNC_SETTINGS)));button("＋ 직접 일정 입력",()->review(null));button("검토함 새로고침",()->home());button("입력 · 연동 안내",()->message("기기 Google 계정의 캘린더 동기화를 켜세요. 확인한 일정은 선택한 Google 캘린더에 저장됩니다. Google 동기화 후 PC에서 계정을 연결하고 강제 일정 반영을 누르세요. 카카오톡 전체 대화가 아니라 허용된 알림 내용만 읽습니다. 알림에 내용이 숨겨져 있거나 알림이 오지 않은 대화는 가져오지 못합니다. 실시간 전달은 Android와 Google의 동기화 상태에 따라 지연될 수 있습니다."));text("검토를 기다리는 입력",19,Color.rgb(48,71,107));JSONArray list=LocalStore.queue(this);int count=0;for(int i=0;i<list.length();i++){JSONObject item=list.optJSONObject(i);if(item==null||!"pending".equals(item.optString("state")))continue;count++;String title=item.optString("title");text(title+"\n"+item.optString("text"),13,Color.rgb(90,112,146));button("확인하고 일정에 반영",()->review(item));button("이 입력 제외",()->{try{LocalStore.finish(this,item.optString("id"),"rejected");home();}catch(Exception e){message("저장하지 못했습니다.");}});}if(count==0)text("새로운 입력이 없습니다. 알림 수집을 켠 뒤 카카오톡 알림이 도착하면 여기에서 확인하세요.",13,Color.rgb(132,148,173));button("잠그기",()->{unlocked=false;login("login");});}
 void loadCalendars(){calendarIds.clear();ArrayList<String> labels=new ArrayList<>();if(calendarPermission()){try(Cursor c=getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{CalendarContract.Calendars._ID,CalendarContract.Calendars.CALENDAR_DISPLAY_NAME},CalendarContract.Calendars.ACCOUNT_NAME+"=? AND "+CalendarContract.Calendars.ACCOUNT_TYPE+"=? AND "+CalendarContract.Calendars.SYNC_EVENTS+"=1 AND "+CalendarContract.Calendars.CALENDAR_ACCESS_LEVEL+">=?",new String[]{ACCOUNT,"com.google",String.valueOf(CalendarContract.Calendars.CAL_ACCESS_CONTRIBUTOR)},null)){while(c!=null&&c.moveToNext()){calendarIds.add(c.getLong(0));labels.add(c.getString(1));}}catch(Exception e){}}if(labels.isEmpty())labels.add("권한 허용 후 해당 Google 캘린더 동기화를 켜세요");calendars.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(unlocked)home();}
 void review(JSONObject item){if(!calendarPermission()){message("캘린더 읽기·쓰기 권한을 먼저 허용하세요.");return;}if(calendarIds.isEmpty()){message("해당 Google 계정의 쓰기 가능한 캘린더가 없습니다. 계정을 추가하고 일정 동기화를 켜세요.");return;}long calendarId=calendarIds.get(calendars.getSelectedItemPosition());LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(20),dp(10),dp(20),dp(10));EditText title=new EditText(this),start=new EditText(this),end=new EditText(this);title.setHint("일정 제목");start.setHint("시작: 2026-11-02 14:00");end.setHint("종료: 2026-11-02 15:00");title.setText(item==null?"":item.optString("text").substring(0,Math.min(160,item.optString("text").length())));SimpleDateFormat format=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.KOREA);format.setTimeZone(TimeZone.getTimeZone("Asia/Seoul"));long now=System.currentTimeMillis();start.setText(format.format(new Date(now+3600000)));end.setText(format.format(new Date(now+7200000)));if(item!=null){Matcher date=Pattern.compile("(20\\d{2})[-./년]\\s*(\\d{1,2})[-./월]\\s*(\\d{1,2}).*?([01]?\\d|2[0-3]):([0-5]\\d)").matcher(item.optString("text"));if(date.find()){String s=String.format(Locale.ROOT,"%s-%02d-%02d %02d:%s",date.group(1),Integer.parseInt(date.group(2)),Integer.parseInt(date.group(3)),Integer.parseInt(date.group(4)),date.group(5));try{Date parsed=format.parse(s);start.setText(s);end.setText(format.format(new Date(parsed.getTime()+3600000)));}catch(Exception e){}}}form.addView(title);form.addView(start);form.addView(end);TextView info=new TextView(this);info.setText("날짜·시간을 반드시 확인하세요. 종료는 기본 1시간 뒤입니다. 선택한 Google 캘린더에 저장됩니다.");info.setPadding(0,dp(12),0,dp(10));info.setTextSize(12);form.addView(info);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("일정 확인 · 반영").setView(form).setNegativeButton("취소",null).setPositiveButton("Google 일정에 저장",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{format.setLenient(false);String name=title.getText().toString().trim();if(name.length()<1||name.length()>160)throw new Exception("제목은 1~160자로 입력하세요.");long a=format.parse(start.getText().toString()).getTime(),b=format.parse(end.getText().toString()).getTime();if(b<=a)throw new Exception("종료는 시작보다 나중이어야 합니다.");android.net.Uri.Builder range=CalendarContract.Instances.CONTENT_URI.buildUpon(); android.content.ContentUris.appendId(range,a); android.content.ContentUris.appendId(range,b); try(Cursor conflicts=getContentResolver().query(range.build(),new String[]{CalendarContract.Instances.BEGIN,CalendarContract.Instances.END},CalendarContract.Instances.CALENDAR_ID+"=?",new String[]{String.valueOf(calendarId)},null)){while(conflicts!=null&&conflicts.moveToNext())if(conflicts.getLong(0)<b&&conflicts.getLong(1)>a)throw new Exception("기존 일정과 겹칩니다. 시간을 조정하세요.");}ContentValues values=new ContentValues();values.put(CalendarContract.Events.CALENDAR_ID,calendarId);values.put(CalendarContract.Events.TITLE,name);values.put(CalendarContract.Events.DTSTART,a);values.put(CalendarContract.Events.DTEND,b);values.put(CalendarContract.Events.EVENT_TIMEZONE,"Asia/Seoul");values.put(CalendarContract.Events.DESCRIPTION,"ORBIT에서 사용자가 확인한 일정");Uri saved=getContentResolver().insert(CalendarContract.Events.CONTENT_URI,values);if(saved==null)throw new Exception("일정을 저장하지 못했습니다.");if(item!=null)LocalStore.finish(this,item.optString("id"),"confirmed");dialog.dismiss();home();message("휴대폰의 Google 캘린더에 저장했습니다. 클라우드 반영은 기기 Google 동기화가 완료된 후 확인하세요.");}catch(Exception e){message(e.getMessage()==null?"날짜와 권한을 확인하세요.":e.getMessage());}}));dialog.show();}
}

